import java.util.Scanner;

public class Main {
    static long inf = 17446744073709551616L;
    static long[][] dp = new long[18][250005];
    static long[] fac = new long[250005];
    static long[] inv = new long[250005];
    static long mod;
    static long n, k;

    static long qpow(long a, long b) {
        long res = 1L;
        long base = a % mod;
        while (b > 0) {
            if ((b & 1L) == 1L) {
                res = (res * base) % mod;
            }
            base = (base * base) % mod;
            b >>= 1;
        }
        return res;
    }

    static long cal(int a, int b) {
        return (((fac[a] * inv[b]) % mod) * inv[a - b]) % mod;
    }

    static long compute() {
        for (int i = 0; i <= n; i++) {
            fac[i] = 1L;
        }
        for (int i = 1; i <= n; i++) {
            fac[i] = (fac[i - 1] * i) % mod;
        }
        inv[n] = qpow(fac[n], mod - 2);
        for (int i = n - 1; i >= 0; i--) {
            inv[i] = (inv[i + 1] * (i + 1)) % mod;
        }
        for (int i = 1; i <= n; i++) {
            dp[1][i] = inv[i];
        }
        long answer = (dp[1][(int) n] * cal((int) k, 1)) % mod;
        int t = (int) Math.min(17, k);
        for (int i = 2; i <= t; i++) {
            for (int j = (int) n; j >= 1; j = (j - 1) & (int) n) {
                for (int l = j; l >= 1; l = (l - 1) & j) {
                    dp[i][j] += dp[i - 1][j ^ l] * inv[l];
                    if (dp[i][j] > inf)
                        dp[i][j] %= mod;
                }
                dp[i][j] %= mod;
            }
            answer += dp[i][(int) n] * cal((int) k, i);
            answer %= mod;
        }
        answer = (answer * fac[(int) n]) % mod;
        return answer;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextLong();
        k = sc.nextLong();
        mod = sc.nextLong();
        long ans = qpow(k, n);
        if ((n & 1) == 1) {
            System.out.println(ans);
            return;
        }
        ans = (ans - compute() + mod) % mod;
        System.out.println(ans);
        sc.close();
    }
}
